import{_ as a,c as e,o as t,ah as i}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易經傳集解卷二十八","description":"周易經傳集解 - 周易經傳集解卷二十八","frontmatter":{"title":"周易經傳集解卷二十八","description":"周易經傳集解 - 周易經傳集解卷二十八"},"headers":[],"relativePath":"classics/jingchuan-jijie/029.md","filePath":"classics/jingchuan-jijie/029.md"}'),s={name:"classics/jingchuan-jijie/029.md"};function n(c,p,r,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[i('<p>欽定四車全書</p><h1 id="周易經傳集解卷二十八" tabindex="-1">周易經傳集解卷二十八 <a class="header-anchor" href="#周易經傳集解卷二十八" aria-label="Permalink to “周易經傳集解卷二十八”">​</a></h1><p>宋林栗撰</p><p>序卦曰：得其所歸者必大，故受之以豐。豐者，大也。</p><p>「豐」，「歸妹」之變也。「歸妹」之豐，上震不動，下兌為離，二三相易而成卦也。兌，少女；離，中女。少女而歸長男，所以為歸妹也。兌之從震，必徵乎離。萬物相見之時，取諸豐盛，不亦宜乎？</p><p>豐：亨，王假之。勿憂，宜日中。彖曰：豐，大也。明以動，故「豐」。「王假之」，尚大也。「勿憂，宜日中」，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？</p><p>下離上震，成卦曰「豐」者，初為離，二為巽，三為兌，四為震。離，明也；震，動也。明以動謂之「豐」，何也？為其有巽、兌之象焉。巽，入也；兌，說也。一陽在上，三陰承之，春氣發而百草生，正得秋而萬寶成，是以謂之「豐」也。離，中女也；震，長男也。中女長男謂之「豐」，何也？為其有巽、兌之象焉。巽，長女也；兌，少女也。一男當室，三女從之。天子有九御，諸侯有三歸，是以謂之「豐」也。昔周共王遊於㴛上，密康公從，有三女奔之。其母曰：必致之王。人三為眾，女三為粲。夫粲，美之志也。眾以美物歸女，而何德以堪之？故子曰：「豐，大也。明以動，故豐。」愚謂：下「豐」字當作「亨」字，豐亨之義也。按爾雅：苞、蕪、茂，豐也。豐文生於手，說文曰：「草盛豐豐也。」豐之二五，皆體乎巽，巽為蕃鮮，故有蕃盛之義，亦有蔽障之義焉。雜卦曰：「豐，多故也。」當豐之時，業巨事叢，朝廷尊安。尊則易驕，安則易惰。驕則日入於壅蔽之域，情則日淪於委靡之塗。惟明，故壅蔽之患不生；惟動，故委靡之漸不作。漢之元帝、唐之文宗，不足於明故也；漢之成帝、唐之穆宗，不足於動故也。天下久安，內外旡患，因循苟且，必有偏而不起之處。惟明以動，故能舉偏而補弊，通變而不窮，此其所以亨與！王假之，何謂也？曰：假，大也。夫所謂豐者，豈直土地之廣，人民之眾也哉？謂夫兵寢刑措，禮制樂作，上恬下熙，家給人足，蕃衍盛大，乃為豐也。原其所以致此者，孰使然哉？王實大之也。故子曰：「王假之，尚大也。」治天下者，審所尚而已。所尚者大，則其功博；所尚者小，則其效卑，必然之理也。賈誼曰：「天下者，器也。置之安處則安，置之危處則危。」魏徵曰：「行帝道而帝，行王道而王，顧所行何如耳。」而昧者以為治亂在天，安危任數，遂廢人事而不修，是不知天道也。說天者莫辯乎易，易之言如是，學者可以察矣。「勿憂，宜日中」，何謂也？曰：此聖人之所以處豐也。說者皆謂當斯之時，可以旡憂，愚謂不然。夫亨者，極盛之詞也；勿者，禁止之辭也。書曰：「無疆惟休，亦無強惟恤。」又曰：「無疆惟休，亦大惟艱。」而況易之為書，告人以進退存亡、吉㓙得喪相為倚伏之理，惟恐不切至，故常言</p><p>天地、日月、四時、鬼神以曉譬之，而豈以極盛之時，乃止之使勿憂乎？泰之九三曰：「旡平不陂，旡往不復，勿恤其孚，於食有福。」晉之六五曰：「悔亡，失得勿恤。」夬之</p><p>九二曰：「惕號，莫夜有戎，勿恤。」家人之九五曰：「王假有家，勿恤，吉。」而豐之彖曰：「勿憂，宜日中。」此五象者，皆當文明極盛之時，愚人之所不憂，而聖人以為深憂，故其辭皆言「勿恤」者，深切之辭也。猶言天下盛極矣，能勿憂乎？故泰之「勿恤」，在平陂之間；晉之「勿恤」，在失得之際；夬之「勿恤」，在於「莫夜有戎」。家人之辭與豐相類，皆言王實大之，而可以勿憂乎？詩云：「母念爾祖，聿修厥德。」亦深切之詞也，故曰「宜日中」。蘇氏曰：「宜日之中，而不宜其既中也。夫有晝必有夜，有中必有昃，雖人不能易也，其能使之勿昃乎？易曰：日昃之離，不鼓缶而歌，則大耋之嗟。而此言宜日中者，何也？子曰：宜照天下也。蓋豐之患，患在下情不得上達，上情不能下通，宜廓其照，如日之方中，不宜障蔽其明，如蔀屋之下也。昔者帝堯光宅天下，被於四表，至於海隅蒼生，萬邦黎獻，共惟帝臣，嘉言罔伏，野無遺賢，不虐無告，不廢困窮，斯日中之豐也，其有不亨者乎？」夫子既釋其義，又從而暢之曰：「日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？」由此言之，豐大之時，聖人之所畏也。說者乃謂無憂而可，豈不過甚矣哉！</p><p>象曰：雷電皆至，豐，君子以折獄致刑。</p><p>雷者，震也。電者，離也。雷電皆至，威明震耀之象也。君子以之「折獄致刑」者，明以折其情，威以致其罰也。而說者祖荀卿之論，以致刑為極刑，且言治世刑重，則失之遠矣。舜典、皋陶惟明克允。故易凡言刑獄之事，未嘗不取諸離。離也者，明也。明以動，折獄致刑之象也；明以止，無敢折獄之象也。動而明，明罰敕法之象也；止而明，明慎用刑之象也。明罰敕法，王者之事，故言先王。折獄致刑，有司之事，故言君子。君子者，通上下而言，故旅之「明慎用刑」，賁之「明庶政」，通稱君子也。雜卦曰：「豐，多故也。」</p><p>豐之為卦，以物之盛大而成，其在六爻，以世方多故為義。故，猶事也。當豐之時，天下可謂無事矣，而謂之多故，何哉？曰：天下惟有事也，然後知無事之為安。及其無事也，又將生事以為樂。雖然，亦其𫝑之不得不然也。書雲：「位不期驕，祿不期侈。」今夫小民，方其脫於凍餒之中，苟可以糊其口，蔽其形，斯亦足矣，尚何事之有哉？及其有田以食，有廬以處，生生之資，稍稍充牣，則其口腹耳目之奉，婚姻伏臘之資，死喪賓客之度，豈能複視曏者凍餒之時乎？此其所以多事也。天下國家亦猶是矣。富其蕃衍盛大之時，有不期豐而自豐者，顧所以自豐如何耳。豐其德，豐其典禮，豐其賢才，豐其法度，則本益固而末益茂。苟為不然，豐其宮室，豐其貨利，豐其女子，豐其便嬖，則其所以自豐，乃所以自蔽也。是故豐有蕃盛之義，亦有蔽障之義焉。謂之多故，不亦宜乎？豐之諸爻，初九以六二為配主，九四以六五為夷主。九三、上六雖居正應之地，有「艮」「兌」之情，而不相遇焉。三「折其右肱」，上「闃其無人」者，蓋有物以蔽之也。說者皆以初當配四，二當應五。若如所論，是陰與陰配，陽與陽配，旡自而相得矣。又曰：初、四同德相求，初為夷主，四為配主。兩皆為主，則莫適為配矣。又曰：初遇四為配主，遇五為夷主。以一遇二，四為陽而五為陰，其於初九不能相當，益為繆戾難合矣。夫應在遠，不可以言遇。遇者，適相值也。「姤」之卦，其訓為「遇」。故初六在下，繫於九二，而他爻爭之則㓙。今初與二，四與五，皆以近相值而合，夫是以稱「遇」也。或曰：睽諸文皆言「遇」，皆其應也，此獨非應，何耶？曰：「睽」以乘離為義，六爻分散而不得相值，適其配而合焉，故可以言「遇」。「豐」以障蔽為義，九三、上六猶不相遇，而況初、四皆陽，二五皆陰，何自而遇哉？或曰：初與二遇，安得為配？而四與五遇，又曷為夷？二五皆陰，何以為主？曰：初以純剛而遇二純柔，安得不為配？四不純剛而五不純陰，安得不為夷？二五雖柔，而居中得位，安得不為主？「夷」，平也。初九之與六二，強弱異勢，得為平乎？此「豐」之所以為多故也。</p><p>初九：遇其配主，雖旬旡咎，往有尚。象曰：「雖旬旡咎」，過旬災也。</p><p>初九，「離」也。以陽居剛而在下卦之下，上旡其應，而承六二之「巽」，故曰「遇其配主」。初九之於六二，一陰一陽，是其配主矣，故曰「雖旬旡咎」。十日謂之「旬」，「旬」猶滿也。九者數之極而加以初一，故有「十」之象焉。夫所惡於滿者，為其溢也；所畏於盈者，為其虧也。日之中，月之望，皆有滿盈之象，故「歸妹」六五以「月幾望」為「吉」，而「豐」之彖曰「宜日中」者，謹其所以持之而已矣。今以九居初而當「豐」之時，可謂滿矣。為其遇於六二，有剛柔相濟之象，是以雖滿而「旡咎」也，故曰「往有尚」。「尚」，猶配也。既曰「遇其配主」，而又曰「往有尚」者，為其志在於自豐，有時而不往也。故子曰：「雖旬旡咎，過旬災也。」孝經曰：「滿而不溢。」其斯之謂歟！</p><p>六二：豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。象曰：「有孚發若」，信以發志也。</p><p>六二，「巽」也，以陰居柔而在下卦之中，上旡其應，而介於初九、九三之間，二爻皆「離」，而三又「兌」也，故曰「豐其蔀，日中見鬥」。「蔀」，覆也，所以蔽日者也。三居下卦之上，自二視之，皆有「蔀」之象焉，而又以陽居剛，是以謂之「豐其蔀」也。二居中而上下皆「離」，故有「日中」之象。二體「巽」，「巽」為入，故有入於蔀覆之象。日之方中，旡所不照，而「豐其蔀」以自覆，則所見者鬥而已。「鬥」，星斗也。日中無見鬥之理，所以云爾者，居蔀覆之下，蓋有孔罅容光者焉，則曰「見鬥而不見日」，固其宜矣。鬥有七星，全卦中之體九畫，六二為日中，其餘七畫，「鬥」之象也。陰四畫為「鬥」，陽三畫為「杓」。日隱而鬥見，「日中見鬥」之象也。日中為「鬥」，何謂也？曰：人之聰明足以照知四遠，而為物所蔽，則聽於讒謟近習，而以察為明，雖在日中，見鬥而不見日矣。見鬥而不見日，然且自以為明，則受欺於奸諛而不悟也。故曰：「往得疑疾，有孚發若，吉」。巽為進退，為不果，故有「疑疾」之象。三體離「兌」，二女既同居矣，「巽」又往焉，能旡疑乎？故易曰：「一人行，三則疑也」。二往於三而得疑疾，然後以初九之離，發其豐蔀之蔽，是以系之吉也。孟子曰：「人恆過，然後能改。困於心，衡於慮，而後作。徵於色，發於聲，而後喻。入則無法家拂士，出則無敵國外患者，國恆亡。然後知生於憂患而死於安樂也。」或曰：初與三皆「離」也，以陽居剛，二爻之所同也。三為「蔀」而初為「發」，何哉？曰：三之「離」，有「兌」之象焉。「兌」者，日之昃也，而又居過中之位，則其所以為明者，乃其所以自蔽也。謂之「豐蔀」，不亦宜乎？所以然者，當「豐」之時，盛滿為累，初、二為配，相與以成矣。又蔽於三而遇焉，則政失其中，上下壅塞，將窮其大而失其所居矣。此聖人之畏也。故子曰：「有孚發若，信以發志也。」其初九之謂乎？</p><p>九三：豐其沛，日中見沫，折其右肱，旡咎。象曰：「豐其沛」，不可大事也；「折其右肱」，終不可用也。</p><p>九三上體為「兌」，下體為「離」，以陽之上應乎上六之「艮」，而乘乎六二之「巽」，上承九四。四，震兌也，故曰「豐其沛，日中見沬」。古本作「豐其旆」，幡幔之屬也。四體「震」，震為動而不純乎剛，故有幡幔之象。以九居三，過乎剛矣。而益之以九四，是「豐其沛」也。三雖有上六之應，而四為之蔽，如幡幔之蔽明矣。以蔀為未足，又加沛以自障，則日中所見者，沫而已。「沫」，微星也。或曰：鬥後小星也。「見沬」雲者，言其容光之益小也。既「豐其蔀」，又「豐其沛」，非徒不見日，且不見鬥矣。六二為日中，其餘畫七，猶有鬥象。九三為「日中」，其餘不止於七，則小星無名數之象也。或曰：九三何以為日中？曰：三有「離」象，「離」，南方也，日之中天也。故曰：「折其右肱，旡咎。」九三應在上六，上體「艮」，「艮」為手，居卦之上，有「右肱」之象焉。三體「兌」，「兌」為毀折，故有「折肱」之象焉。人之所恃以為用者，手足耳目而已。今也「豐其沛」，自蔽其明也；「折其右肱」，自蔽其動也。又誰咎乎？故子曰：「豐其沛，不可大事也。」言不足與有明也。「折其右肱，終不可用也」，言不足與有為也。或曰：既已自蔽其明矣，而猶可小事，何哉？曰：當豐之時，法行令具，上恬下熙，以之小事，孰能違者？特其君不明，則不可大有為耳。洪範所謂「作內吉，作外㓙」，亦其意也。然積日累月，將有三歲不覿之兇矣。</p><p>九四：豐其蔀，日中見鬥，遇其夷主，吉。象曰：「豐其蔀」，位不當也。「日中見鬥」，幽不明也。「遇其夷主」，吉行也。</p><p>九四上體為「震」，下體為「兌」，以陽居柔而在上卦之下，下旡其應，而承於六五之「巽」，故曰「豐其蔀，日中見鬥」。六五之於九四，可謂「發其蔀」矣，而乃曰「豐其蔀」，何哉？曰：非九四之以六五為「蔀」也，乃六五之以上六為「蔀」也。六五之以上六為「蔀」，何也？曰：「蔀」，覆也，且言周密也。九三、上六居一卦之上，而以陽居剛，以陰居柔，有掩覆周密之象，是以同稱「蔀」也。六五為日中，而「豐其蔀」以自蔽，則所見者鬥而已，猶六二「見鬥」之象也。六五何謂「日中」？曰：「豐」之二五，即「離」之二五，有日中之象焉。所以變「離」為「豐」者，上九一爻之易也。則上之為「蔀」，不亦宜乎？然而不言於五而言於四者，此則聖人互文見義，因九四有夷主之遇，而遂當六五之辭，不使學者易而知之耳。如使六二、六五兩著其文，則學者怠而不思，而得非微顯闡幽之自也。故子曰：「豐其蔀，位不當也。日中見鬥，幽不明也。」謂上六居一卦之極，不當其位，而六五受其掩蔽，有幽不明之象焉。苟非「巽」乎九四之剛，何以獲慶譽之吉矣？故曰：「遇其夷主，吉。」九四之於六五，有夷主之象焉。「夷」，平也。所謂君臣同德，上下相需者也。晏子曰：「君所謂可而有否焉，臣獻其否以成其可；君所謂否而有可焉，臣獻其可以替其否。」六五，君也，九四，臣也。五以陰居剛，而四以陽居柔。五體巽巽以下逮，四體震震以上行。此無太過，彼旡不及，謂之夷主，不亦宜乎？是以系之吉也。或曰：九四之震，有兌象焉，其能與五為夷，何也？曰：兌上無其與，下無其應，是震之輔也。有震無「兌」，則九四之剛或幾乎過矣。震，動也；「兌」，說也。此四之所以為平也。故子曰：「遇其夷主，吉，行也。」行也者，其動象乎！六五：來章，有慶譽，吉。象曰：六五之「吉」，有慶也。</p><p>六五，「巽」也。以陰居剛而在上卦之中，下旡其應而乘九四。四，「震兌」也，故曰「來章」。一陰一陽，合而成章。六五之於九四，所謂「來章」也。六二上有九三，故「往得疑疾」，然後「有孚」於初六。五上旡其應，故直言其來也。以「巽」從「震」，有不約而來者矣，故曰「有慶譽，吉」。陰之獲陽，謂之「有慶」。「有慶」而又「有譽」者，為其能「巽」以下賢故也。歡欣交通，聲名洋溢，其斯之謂歟？故子曰：「六五之吉，有慶也。」</p><p>上六：豐其屋，蔀其家，𬮭其戶，闃其無人，三歲不覿㓙。象曰：「豐其屋」，天際翔也。「𬮭其戶，闃其無人」，自藏也。</p><p>上六，「艮」也，以陰居柔，而在上卦之上，應九三之「兌」，而乘六五之「巽」，故曰「豐其屋，蔀其家」。上六以陰居柔，體是「艮」止，出陰之所，闇昧之時也。有應在三，隔於六五而不相遇焉，有物以蔽之也。處於至高，而重陰以自固，「豐其屋」之象也。既以重陰，而又以陰自蔽，「蔀其家」之象也。屋之為覆，高大周密，非直蔀與旆也。以屋為未足，又施蔀於其家。家，屋中也，其自為障蔽又甚矣。沫之微明且不得見，而況於鬥與日乎？故曰「𬮭其戶，闃其無人」。「𬮭其戶」，其戶閒也。「闃其無人」，其人亡也。艮為止，為門闕，有閉戶之象焉。巽為入，為伏，故有「無人」之象焉。堂下遠於百里，君門遠於萬里。「闢四門，明四目」，猶懼壅塞，而況閉之乎！貴而旡位，高而旡民，賢人在下位而旡輔，所與居者，讒謟近習而已，所謂「闃其無人」者也。屋高而蔀盛，戶閉而室窒，人亡而鬼瞰，欲無㓙，得乎？故曰「三歲不覿㓙」。夫禍患之來，非一日之故也。壅蔽之患，生於闇昧；委靡之勢，成於宴安。逮夫邪佞滿前，忠良廢斥，綱紀敗壞，風俗陵夷，人心攜離，主勢孤立，如此者，豈一日之故哉？其所由來者漸矣。偷安朝夕，幸或可以無他，曠日持久，未嘗不至於大亂。揚子曰：「三年不日，日視必盲；三年不目，目晴必蒙。」今也深藏而遠匿，失人而絕物，至於三歲之久而旡所見焉，㓙斯至矣，秦二世是也。外倚長城之強，內增阿房之固，自以為帝王萬世之業，可謂豐其屋而蔀其家矣；忠諫者族，偶語者棄市；誅大臣，滅宗室，深居高拱，使群臣但聞其聲，不得見其面，可謂𬮭其戶，寂其無人矣；山東之盜，指為妖言；宮中之鹿，指而為馬；天下之士，相率以逃秦難，而趙高之徒日侍左右，伺其隙而圖之，可謂人亡而鬼瞰其室矣。三歲不覿，㓙其宜乎？子曰：豐其屋，天際翔也；𬮭其戶，闃其無人，自藏也。屋翔於天際，而自藏於蔀中，其可謂之不祥矣。</p><p>序卦曰：「豐者，大也。窮大者必失其居，故受之以旅。」旅，豐之反也。自豐之旅，離反居上，震反為艮，上下相易而成也。離，麗也；「震」，動也；「艮」，止也。動而麗乎內，所以為豐也；止而麗乎外，所以為旅也。若夫家人之象，亦取其人而麗乎內矣。夫物禁太甚，其極必反。「豐」之上六，其大窮也，是以大其豐屋蔀家而為旅也。秦二世末年，為趙高所紿，出居望夷之官，豈非窮大者失其所居之驗乎？</p><p>旅：小亨，旅貞吉。彖曰：「旅，小亨」，柔得中乎外而順乎剛，止而麗乎明，是以「小亨，旅貞吉」也。旅之時義大矣哉！</p><p>下艮上離，成卦曰旅者，初為艮，二為巽，三為兌，四為離。艮，止也；離，明也。止而麗乎明，斯謂之旅，可乎？曰：未也，為其有巽、兌之象焉。巽，入也；兌，說也。入而說之，則寓人之情可見矣，是以謂之旅也。艮，東北也；離，南方也。自東北而之乎南，非其類，又非其配也，謂之旅可乎？曰：未也，為其有巽、兌之象焉。巽，東南也；兌，西方也。方以類聚，而艮獨寓焉，是以謂之旅也。「旅小亨，旅貞吉」，何謂也？曰：小亨者，卑小而後亨也；貞吉者，貞固而後吉也。夫旅者，違其國，去其家，而託於他人者也。苟亢傲自尊，與物屏絕，則窮困而莫之救矣；輕躁妄行，先時而動，則顛沛而無所歸矣。惟能卑小而下人，然後可以冀其亨；惟能貞固而待時，然後可以保其吉。是以旅之二五，其畫皆柔，其體皆巽，柔巽以行之，是以系之「小亨」也。下卦為艮，上卦為離，止而麗乎明，是以系之「貞吉」也。故子曰：「旅小亨，柔得中乎外而順乎剛，止而麗乎明，是以小亨，旅貞吉也。」上文「小亨」二字疑是衍文。旅之二五，皆柔得中，而但言得中乎外者，六二之義未可以亨，至五而後亨也。得中乎外，然後為旅。若得中乎內，旅之云乎？曰：然則二之得中，何謂也？曰：此所謂「貞吉」者也。以柔居剛，上有所託，下有所輔，是以能亨。以柔居柔，上無所託，而下無所與，其能亨乎？貞固守之，斯為吉也。故曰：「旅之時義大矣哉！」夏少康、周宣王、齊威、晉文、衛文、趙武，應其時義矣。說者或曰：「旅卦為孔、孟歷聘周遊之義。」非也。孔、孟東西南北之人也，視旅猶家也，豈所謂窮大而失其所居者乎？豈所謂「柔得中而順乎剛，止而麗乎明」者乎？斯不待辯而明矣。</p><p>象曰：山上有火，旅，君子以明慎用刑，而不留獄。</p><p>山者，「艮」也；火者，「離」也。山上有火，非火之所歸，是以謂之「旅」也。君子以之明謹用刑而不留獄者，明取諸「離」也，慎取諸「艮」。火行則山無餘蓄，刑用則獄無留情，是以君子有取於斯也。雜卦曰：「親寡，旅也。」旅之為卦，以失其所居而成。其在六爻，以所親眾寡為義。何則？旅者，去國之流人也。所親者寡，不亦宜乎？陽為剛，陰為柔。剛者，人之所託也；柔者，託於人者也。上為尊，下為卑。尊者，人之所託也；卑者，託於人者也。是故「旅」之諸爻，以陰託於陽、以下託於上者，得其所託者也；以剛託於柔、以上託於下者，失其所託者也。初六有「志窮」之災，六二有「即坎」之貞，九三有「焚次」之厲，九四有「於處」之安，六五有「射雉」之譽，上九有「焚巢」之㓙者，各以其所親眾寡而辯之矣。</p><p>初六：旅瑣瑣，斯其所取災。象曰：「旅瑣瑣」，志窮災也。</p><p>初六，「艮」也。以陰居剛，而在下卦之下，承六二之「巽」，而應乎九四。四，離兌也，故曰「旅瑣瑣」。「瑣瑣」，小之志也。「旅」之初六，即「豐」之上六。「豐」，大也。窮於大，必反於小，故「旅」之初六，至於「瑣瑣」也。六二陰柔，既不足以為託，而於初六亦無相比之情，四雖其應，而旅於他邦，不能以相援，處於最下，體乎艮止，卑辱已甚，而旡改轍之圖，二體巽巽，為近利市三倍，初六承之，其志已細，是以謂之「瑣瑣」也。君子見其在旅之「瑣瑣」，而知其所以取災，故曰「斯其所取災」。方其在豐也，甘於闇昧，溺於宴安，養尊處高，自絕於物；及其在旅也，不順乎剛，不麗乎明，而徒苟朝夕之安，爭尋常之利，此其所以「取災」也。故子曰：「旅瑣瑣，志窮災也。」不能保其宗廟社稷而旅於他邦，必瑣而又瑣，志窮而止此矣。黎侯寓於衛，衛不能圖而黎侯安之，式微之詩所以有「瑣兮尾兮」之刺也。</p><p>六二：旅即次，懷其資，得童僕貞。象曰：「得童僕貞」，終無尤也。</p><p>六二，「巽」也。以陰居柔而在下卦之中，上無其應，而乘初六之「艮」，上承九三。三，震兌也，故曰「旅即次」。「次」，舍也。巽為入，而二又居中，故有「即次」之象。六二之於九三，得其所託矣。二，「巽」也；三，「震」也。以「巽」從震，是以系之「即次」也。</p><p>序曰：「旅而無所容，故受之以巽。」巽者，旅之所容之道乎？故曰：「懷其資，得童僕貞。」「巽」為近利，而二又居中，故有懷「資」之象。「艮」為少男，而在二之下，故有「得童僕」之象。「即次」而懷其資，待時之義也。時則未至，未可以亨，而有次可以安，有資可以給，有童僕可以賴，貞固守之，斯為得矣。故子曰：「得童僕貞，終無尤也。」不言吉者，旅於他人無咎，幸矣，何吉之云乎？彖之所謂「吉」者，要其終而言之也。晉文公在狄十有九年，得民之心，得士之力，有趙衰、狐偃以為腹心，有魏犨、賈佗以為股肱。越王句踐棲於會稽二十餘年，親其人民，厚其貨財，有大夫種以治其外，有范蠡以治其內，可謂「即次」而懷資，「得童僕貞」者矣。衛侯衎之出也，厚成叔吊於衛，歸語臧孫曰：「衛君其必歸乎？有太叔儀以守，有母弟鱄以出，或撫其外，或營其內，能無歸乎？」及臧孫唁於郊，見子展、子鮮，亦曰：「衛君必入矣。」二子者，或挽之，或推之，欲無入，得乎？此其得童僕，是以終無尤也。九三：旅焚其次，喪其童僕，貞厲。象曰：「旅焚其次」，亦以傷矣。以旅與下，其義喪也。</p><p>九三上體為兌，下體為震，以陽居剛而在下卦之上，上無其應，而承九四之離，乘六二之巽，故曰：「旅焚其次，喪其童僕。」三之所託者，四也。三於四為強矣，而反託之兩剛，不能以相事。四又體離，離為火，故有焚次之象焉。三之所乘者，二也。二禮巽，三禮震，以巽承震，故亦有童僕之象焉。然巽為進退、為不果，震為決躁，兌為毀折，故有「喪其童僕」之象焉。在旅無親，所親者童僕，惟以身處柔讓，而從者強力，然後可以脫於危難之中。今九三以陽居剛，而六三以陽居柔，是身為強暴，而童僕𡯁羸，又有毀折之象焉，是以知其童僕之喪矣。次舍既焚，童僕又喪，而猶貞固守之，危之道也。故曰「貞厲」。子曰：旅焚其次，亦以傷矣。以旅與下，其義喪也。身為旅人，亢傲自尊，輕躁妄動，不能親上而務與下交，宜其喪也。魯昭公孫於齊，齊侯取鄆以居之。昭公據鄆以與魯戰，既而鄆人潰叛，齊、晉卑之，有子家羈而忽其謀，有叔孫婼而致其死。春秋三十二年書「公在乾侯」，言內外不能用其人也。其九三之謂乎？或曰：子以艮為童僕，六二非艮也，而有童僕之象，何哉？曰：此相因而成象也。「坤」之「龍戰」，「大壯」之「喪羊」，亦猶是矣。</p><p>九四：旅於處，得其資斧，我心不快。象曰：「旅於處」，未得位也；「得其資斧」，心未快也。九四上體為「離」，下體為「兌」，以陽居柔而在上卦之下，應初六之「艮」，而承六五之「巽」，下乘九三。三，震兌也，故曰：「旅於處，得其資斧。」四已進乎上卦，而未得其中，託於六五，雖剛柔無以相尚，而有相與之情，是亦得其所託矣，故有「於處」之象焉。「資」，當作「齊」。說文曰：「子夏傳及眾家皆作齊斧。」應劭雲：「齊，利也。」漢書：「王莽遣王尋屯洛陽，將發，亡其黃鉞。」其士房楊曰：「此經所謂喪其齊斧者也。」四「離」體「兌」，「兌」為金，「離」為戈兵，又以陽居剛，故有「齊斧」之象焉。夫「旅」者，失其所居者也。而四有「於處」之辭，是將復其國者也。「得其資斧」，是執其威柄者也。然其位不中，其應在下，有「艮兌」之情，而不得相遇焉，故曰「我心不快」。得其處而未得其位，「得其資斧」而未得其用，其心安得而快乎？所以然者，在旅之時，惟「巽」為可以貞，惟「巽」為可以「亨」。今九四離乎「離兌」，是以未逞其志也。故子曰：「旅於處，未得位也。得其資斧，心未快也。」鄭厲公之在櫟，衛莊公之在戚，所謂「旅於處而未得位」者與？然二君者，不足以充九四之義，四蓋六五之未得志者也。說者謂於處不若即次之安。按春秋書昭公次於陽州，次於乾侯。陽州，齊地也。乾侯，晉地也。書「公至自齊，居於鄆」。左氏曰：「公至自齊，處於鄆，言魯地也。」由是言之，「次」者寓於他人，而處者入其故國也。二遠於五，而四已近之，此其所以不同興。</p><p>六五：射雉，一矢亡，終以譽命。象曰：「終以譽命」，上逮也。</p><p>六五，「巽」也，以陰居剛，而在上卦之中，下旡其應，而介於九四、上九之間，二爻皆「離」，而四又「兌」也，故曰「射雉，一矢亡」。「離」為文明，為飛鳥，為弧矢，故有「射雉」之象。四之「離」，有「兌」象焉。「兌」為毀折，故有「一矢亡」之象。「一矢亡」者，先鈍而後利之義也。夫射雉者，豈以一矢之喪而遂去之哉？五，君位而六居之，其體巽巽為入。上有所託，下有所輔，而又有獲文明之象焉。此失國之君，藉內外之𫝑，誅其讎，入其國，而復其位者也，能無一矢之亡乎？唐憲宗曰：「勝負兵家之常，豈得因渠一敗，便沮成計乎？」故爻辭不復稱「旅」，而曰「終以譽命」。彖之所謂「柔得中乎外而順乎剛，是以小亨」者也。說者或謂射以一矢而亡其雉，不惟文意不順，而六五居二「離」之間，射用一矢，於象疏矣。故子曰：「終以譽命，上逮也。」命，爵命也。「以譽命」者，得譽於下，而受命於上也。為天子者命於天，為諸侯者命於天子，為大夫者命於諸侯，皆射矢獲之象也。謂其承於上九，是以自天命之矣。或曰：「離為弧矢，則四、上二爻當之矣，而六五為射雉之象，何哉？」曰：九四者，六五之未得志者也。六五、上九者，九四之成功者也。故一矢之亡，不足以損其大計也。四蓄其資，五收其用，「離」為麗，「巽」為入，系之於五，不亦可乎？或曰：「上焚其巢，則五將安所託乎？」曰：五之有上，五之託也。上焚其巢，已極之災也。楚靈、齊湣，方其盛也，豈不足以為託乎？</p><p>上九：鳥焚其巢，旅人先笑後號啕，喪牛於易，㓙象曰：以旅在上，其義焚也。「喪牛於易」，終莫之聞也。上九，離也。以陽居柔，而在上卦之上，下無其應，而乘六五之「巽」，故曰「鳥焚其巢」。離為火，為飛鳥，為科上稿巽，為風，故有「鳥焚其巢」之象。在旅時，以剛居上，炎炎之極，則有自焚之禍災，故曰「旅人先笑後號啕」。「旅人」，謂九三也。三與上應，三為旅而上為巢也。二爻皆以剛居上，旡相與之情，故三焚其次，上焚其巢。「三焚其次」者，承於九四之離，為他人之所焚也。「上焚其巢」者，自焚也。三體兌震，「兌」為說，震為大聲，故有「先笑後號啕」之象。夫旅者，本失其巢矣，初幸其焚，故笑；後無所歸，故「號啕」也。或曰：下卦，內也；上卦，外也。今六二、九三為次，而六五、上九為巢，何也？曰：為其在旅，故內其次而外其巢矣。婦人內夫家而外父母家，亦猶是也。故曰喪牛於易㓙。易，疆埸也。九居一卦之外，有疆埸之象焉。牛，順物也。「坤」之三女，皆有牛象，猶震、坎、艮之稱馬也。上九乘於六五，五體「巽」，故有牛之象焉。「離」有蓄牝牛之吉，而上九之離至於「喪」者，為其以剛在上，窮其力而至於奔也。書曰：「馬牛其風。」是以九三之焚其次，則巢猶在也；喪其童僕，則牛尚存也。巢在則有可歸之理，牛存則有可行之資。今也巢焚而牛喪，欲歸則無其所，欲行則無其資，㓙斯至矣。故子曰：以旅在上，其義焚也。九三、上九，其為在上，而與下則同，蓋互相發耳。喪牛於易，終莫之聞也。疆埸遠於城邑，人所不聞，以喻上九失人而絕物，故自焚自喪而莫之救也。魏公子無忌客於趙，秦日夜出兵攻魏，魏急而公子不救。毛公薛公謂曰：「公子之所以重於趙者，以有魏也。使秦破魏而夷先王之宗廟，公子當何面目立於天下乎？」此焚巢之喻也。齊崔氏之亡也，杼以難告，慶封帥甲以攻崔氏，殺其妻子而俘其家，覆命於崔子，且御而歸之。至則無歸矣，乃縊。此先笑後號啕之喻也。周易經傳集解卷二十八，</p>',38)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
